fn is_palindrome(text: Vec<char>) -> bool {
    // Helper to lowercase only ASCII uppercase letters A-Z
    fn ascii_to_lower(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    for i in 0..(len / 2) {
        if ascii_to_lower(text[i]) != ascii_to_lower(text[len - i - 1]) {
            return false;
        }
    }
    true
}